using namespace stereoforge;using json=nlohmann::json;using Clock=std::chrono::steady_clock;
inline void check(bool b,const char* m){if(!b)throw std::invalid_argument(m);}
inline uint32_t number(std::string const& s){uint32_t v=0;auto[e,c]=std::from_chars(s.data(),s.data()+s.size(),v);check(c==std::errc{}&&e==s.data()+s.size(),"invalid unsigned option");return v;}
inline float real(std::string const& s){float v=0;auto[e,c]=std::from_chars(s.data(),s.data()+s.size(),v);check(c==std::errc{}&&e==s.data()+s.size()&&std::isfinite(v),"invalid finite scalar");return v;}
inline void fresh(std::filesystem::path const& p){check(std::filesystem::symlink_status(p).type()==std::filesystem::file_type::not_found,"fresh output required");}
inline void write(std::filesystem::path const& path,void const* data,size_t bytes){fresh(path);int fd=::open(path.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_CLOEXEC,0666);check(fd>=0,"exclusive output failed");size_t at=0;while(at<bytes){auto done=::write(fd,static_cast<const char*>(data)+at,bytes-at);if(done<0&&errno==EINTR)continue;if(done<=0){::close(fd);throw std::runtime_error("output write failed");}at+=size_t(done);}check(::close(fd)==0,"output close failed");}
inline json shader_identities(){return {{"view_depth_shader_source_sha256_pair",DaxaView::depth_shader_identity()},{"depth_shader_source_sha256_pair",DaxaDepthPipeline::shader_identity()},{"preprocess_shader_source_sha256_pair",DaxaPreprocess::shader_identity()}};}
inline bool getter(int argc,char** argv){if(argc==2&&std::string(argv[1])=="--shader-directory"){std::cout<<DaxaView::shader_directory()<<'\n';return true;}if(argc==2&&std::string(argv[1])=="--shader-source-identities"){std::cout<<shader_identities().dump()<<'\n';return true;}return false;}
struct Options {
    std::map<std::string,std::string> values;bool validation=false;
    Options(int argc,char** argv,bool fixture){for(int i=1;i<argc;++i){std::string k=argv[i];if(k=="--validation"){check(!validation,"duplicate validation");validation=true;continue;}bool known=k=="--manifest"||k=="--output"||k=="--dump-prefix"||k=="--target-width"||k=="--target-height"||k=="--projection"||k=="--mode"||k=="--fx"||k=="--fy"||k=="--cx"||k=="--cy"||k=="--hfov-radians"||k=="--virtual-from-original-left"||k=="--slots"||k=="--wave-size"||k=="--disparities"||k=="--paths"||k=="--p1"||k=="--p2";known=known||(fixture?k=="--observations-prefix":k=="--frames"||k=="--warmup");check(known,"unknown view-depth option");check(++i<argc,"missing option value");check(values.emplace(k,argv[i]).second,"duplicate option");}check(values.contains("--manifest")&&values.contains("--output"),"manifest/output required");if(fixture)check(values.contains("--observations-prefix")&&values.contains("--dump-prefix"),"fixture observations/dump prefix required");}
    uint32_t u(const char* key,uint32_t fallback)const{auto i=values.find(key);return i==values.end()?fallback:number(i->second);}
    float f(const char* key,float fallback)const{auto i=values.find(key);return i==values.end()?fallback:real(i->second);}
    std::string text(const char* key,std::string fallback)const{auto i=values.find(key);return i==values.end()?fallback:i->second;}
};
inline Pose4 default_original_pose(DaxaStereoCalibration const& original,bool fixture){auto v=identity_pose();if(!fixture)for(unsigned row=0;row<3;++row)v[row*4+3]=float(-.5*original.right_to_left[row*4+3]);return v;}
struct Prepared {
    DaxaPreprocessFixture fixture;CaptureLease source;GeometryConfig config;VirtualView view;DaxaDepthConfig depth;
    std::string manifest_hash,pose_policy;DaxaViewCalibration cache;
    Prepared(Options const& o,bool fixture_input=false){manifest_hash=daxa_preprocess_file_sha256(o.values.at("--manifest"));fixture=load_daxa_preprocess_fixture(o.values.at("--manifest"));auto const& maps=fixture.rectification;check(maps.geometry.has_value(),"calibrated view models required");auto const& g=*maps.geometry;config={maps.width,maps.height,o.u("--target-width",maps.eye_width),o.u("--target-height",maps.source_height)};auto camera=g.original.eyes[0];view.intrinsics={o.f("--fx",float(camera.fx)),o.f("--fy",float(camera.fy)),o.f("--cx",float(camera.cx)),o.f("--cy",float(camera.cy))};view.hfov_radians=o.f("--hfov-radians",1.57079632679f);auto projection=o.text("--projection","perspective"),mode=o.text("--mode","strict");check(projection=="perspective"||projection=="cylindrical","unknown view projection");check(mode=="strict"||mode=="preview","unknown view mode");view.projection=projection=="perspective"?Projection::Perspective:Projection::Cylindrical;view.mode=mode=="strict"?ViewMode::Strict:ViewMode::Preview;
        view.source_to_virtual_left=default_original_pose(g.original,fixture_input);pose_policy=fixture_input?"fixture_original_left_origin":"rig_midpoint_original_left_axes";
        if(o.values.contains("--virtual-from-original-left")){pose_policy="explicit_virtual_from_original_left";std::string csv=o.values.at("--virtual-from-original-left");size_t at=0;for(unsigned i=0;i<16;++i){size_t end=csv.find(',',at);check(i==15?end==std::string::npos:end!=std::string::npos,"virtual transform requires16comma scalars");view.source_to_virtual_left[i]=real(csv.substr(at,end==std::string::npos?end:end-at));at=end+1;}}
        for(unsigned i=0;i<4;++i)for(unsigned j=0;j<4;++j){double value=0;for(unsigned k=0;k<4;++k)value+=double(view.source_to_virtual_left[i*4+k])*g.original.right_to_left[k*4+j];view.source_to_virtual_right[i*4+j]=float(value);}
        cache=prepare_daxa_view_calibration(maps,config,view);depth={StereoConfig{maps.width,maps.height,o.u("--disparities",128),o.u("--paths",4),o.u("--p1",8),o.u("--p2",32),true},1.f,o.u("--slots",2),o.u("--wave-size",32)};depth.validate();depth.requested_buffer_bytes(maps);
        auto replay=packed_replay_source(fixture.capture_directory);auto capture=std::make_shared<CaptureFrame>();for(uint64_t i=0;i<=fixture.record_ordinal;++i)check(replay(*capture,std::chrono::milliseconds(100))==CaptureSourceStatus::recorded_frame,"fixture capture missing");maps.validate_source(*capture);source=std::move(capture);
        std::vector<std::filesystem::path> output_paths{o.values.at("--output")};fresh(o.values.at("--output"));if(o.values.contains("--dump-prefix")){auto prefix=o.values.at("--dump-prefix");for(auto name:{".depth.f32",".confidence.f32",".rgb.u32",".validity.u32",".rgb_validity.u32",".provenance.u32",".source.u32",".approximate.u32",".owner.u32",".source_ids.i64",".age_ns.i64"}){fresh(prefix+name);output_paths.emplace_back(prefix+name);}}std::vector<std::filesystem::path> identities;for(auto const& path:output_paths)identities.push_back(std::filesystem::weakly_canonical(path));std::sort(identities.begin(),identities.end());check(std::adjacent_find(identities.begin(),identities.end())==identities.end(),"overlapping output destinations");
    }
    void verify_inputs(Options const& o)const{check(daxa_preprocess_file_sha256(o.values.at("--manifest"))==manifest_hash&&daxa_preprocess_file_sha256(fixture.capture_directory/"capture.sfp")==fixture.capture_sha256,"fixture changed during run");}
};
inline void dump(GeometryReadback const& data,std::string const& prefix){auto put=[&](auto const& a,const char* suffix){write(prefix+suffix,a.data(),a.size()*sizeof(a[0]));};put(data.depth,".depth.f32");put(data.confidence,".confidence.f32");put(data.rgb,".rgb.u32");put(data.validity,".validity.u32");put(data.rgb_validity,".rgb_validity.u32");put(data.provenance,".provenance.u32");put(data.source,".source.u32");put(data.approximate,".approximate.u32");put(data.owner,".owner.u32");put(data.source_ids,".source_ids.i64");put(data.age_ns,".age_ns.i64");}
inline json report(Prepared const& p,bool overridden){auto const& c=p.config;auto const& s=*p.source;return {{"schema","stereoforge.daxa_view_depth.v1"},{"scope",overridden?"synthetic_known_observation_typed_compositor_fixture_no_stereo_accuracy_or_performance":"repeated_retained_record_actual_depth_and_calibrated_view_no_fresh_camera_qualification"},{"observations_overridden_for_fixture",overridden},{"measured_stereo_output",!overridden},{"metric_source",overridden?"synthetic_known_geometry":"native_dual_reference_SGM_LR_metric"},{"performance_qualified",false},{"rectified_width",c.source_width},{"rectified_height",c.source_height},{"original_width",p.fixture.rectification.eye_width},{"original_height",p.fixture.rectification.source_height},{"target_width",c.target_width},{"target_height",c.target_height},{"virtual_camera_pose_policy",p.pose_policy},{"virtual_from_original_left",p.view.source_to_virtual_left},{"virtual_intrinsics",{p.view.intrinsics.fx,p.view.intrinsics.fy,p.view.intrinsics.cx,p.view.intrinsics.cy}},{"hfov_radians",p.view.hfov_radians},{"virtual_camera_canvas_policy","calibration_left_canvas_unless_explicit_intrinsics_and_dimensions"},{"requested_horizontal_fov_radians",p.view.projection==Projection::Cylindrical?double(p.view.hfov_radians):std::atan((double(c.target_width)-.5-p.view.intrinsics.cx)/p.view.intrinsics.fx)-std::atan((-.5-p.view.intrinsics.cx)/p.view.intrinsics.fx)},{"rgb_valid_coverage",nullptr},{"metric_valid_coverage",nullptr},{"coverage_scope","unmeasured; explicit_posttiming_diagnostic_export_required"},{"projection",p.view.projection==Projection::Perspective?"perspective":"cylindrical"},{"depth_convention",p.view.projection==Projection::Perspective?"virtual_axial_Z":"virtual_ray_range"},{"mode",p.view.mode==ViewMode::Strict?"strict":"preview"},{"map_geometry_association",p.cache.association},{"map_geometry_truth_scope","effective_OpenCV4.14_sample_association_of_supplied_models_not_physical_calibration_truth"},{"preview_valid_count",p.cache.preview_valid_count},{"metric_owner_count",2ull*c.source_width*c.source_height},{"preview_namespace_count",2ull*p.fixture.rectification.eye_width*p.fixture.rectification.source_height},{"preview_only_owner",UINT32_MAX},{"fixture_manifest_sha256",p.manifest_hash},{"capture_sha256",p.fixture.capture_sha256},{"source_metadata",{{"frame_id",s.frame_id},{"camera_timestamp_ns",s.camera_timestamp_ns},{"host_ingress_timestamp_ns",s.host_ingress_timestamp_ns},{"camera_clock_domain",s.camera_clock_domain},{"host_clock_domain",s.host_clock_domain},{"calibration_identity",s.calibration_identity},{"device_identity",s.device_identity}}},{"original_identity",p.fixture.rectification.original_identity},{"rectified_identity",p.fixture.rectification.rectified_identity},{"effective_source_to_virtual_left",p.cache.effective_view.source_to_virtual_left},{"effective_source_to_virtual_right",p.cache.effective_view.source_to_virtual_right},{"source_id",s.frame_id},{"shader_source_identities",shader_identities()},{"compound_cpu_float_reference_checked",false},{"physical_geometry_qualified",false},{"live_60hz_qualified",false}};}
inline void coverage(json& report,GeometryReadback const& data){auto rgb=std::count(data.rgb_validity.begin(),data.rgb_validity.end(),1u),metric=std::count(data.validity.begin(),data.validity.end(),1u);report["rgb_valid_coverage"]=double(rgb)/double(data.rgb_validity.size());report["metric_valid_coverage"]=double(metric)/double(data.validity.size());report["coverage_scope"]="explicit_posttiming_export_target_canvas_pixel_fractions_not_observed_FOV_or_physical_truth";}
inline json summary(std::vector<double> a){std::sort(a.begin(),a.end());return {{"mean",std::accumulate(a.begin(),a.end(),0.)/a.size()},{"p50",a[a.size()/2]},{"p95",a[std::min(a.size()-1,a.size()*95/100)]}};}
inline void finish(Options const& o,json const& report){auto bytes=report.dump(2)+'\n';write(o.values.at("--output"),bytes.data(),bytes.size());}
